package main

import "fmt"

const modulo = 1000000007

type TransitionMatrix struct {
	matrix [4][4]int64
}

func NewTransitionMatrix() *TransitionMatrix {
	return &TransitionMatrix{}
}

func (m *TransitionMatrix) Get(i, j int) int64 {
	return m.matrix[i][j]
}

func (m *TransitionMatrix) Set(i, j int, x int64) {
	m.matrix[i][j] = x
}

func (m *TransitionMatrix) Mul(other *TransitionMatrix) *TransitionMatrix {
	result := NewTransitionMatrix()
	for i := 0; i < 4; i++ {
		for j := 0; j < 4; j++ {
			var x int64 = 0
			for k := 0; k < 4; k++ {
				x = (x + m.Get(i, k)*other.Get(k, j)) % modulo
			}
			result.Set(i, j, x)
		}
	}
	return result
}

func IdentityMatrix() *TransitionMatrix {
	result := NewTransitionMatrix()
	for i := 0; i < 4; i++ {
		result.Set(i, i, 1)
	}
	return result
}

func AntMatrix() *TransitionMatrix {
	result := NewTransitionMatrix()
	for i := 0; i < 4; i++ {
		for j := 0; j < 4; j++ {
			result.Set(i, j, 1)
		}
	}
	for i := 0; i < 4; i++ {
		result.Set(i, i, 0)
	}
	return result
}

func RaiseTo(t *TransitionMatrix, x int) *TransitionMatrix {
	if x == 0 {
		return IdentityMatrix()
	} else if x%2 == 0 {
		tSqr := t.Mul(t)
		return RaiseTo(tSqr, x/2)
	} else {
		tSqr := t.Mul(t)
		return t.Mul(RaiseTo(tSqr, (x-1)/2))
	}
}

func NumPaths(n int) int64 {
	tMatrix := AntMatrix()
	result := RaiseTo(tMatrix, n)
	return result.Get(0, 0)
}

func main() {
	var n int
	if _, err := fmt.Scan(&n); err != nil {
		return
	}
	result := NumPaths(n)
	fmt.Println(result)
}

